package com.clinic.config; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.util.*; import javax.crypto.SecretKey; import org.springframework.stereotype.Component; @Component public class JwtUtil {private final SecretKey key=Keys.hmacShaKeyFor("clinic-secret-key-change-this-to-a-long-secure-32-byte-key".getBytes()); public String generate(String u,String r){return Jwts.builder().subject(u).claim("role",r).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(key).compact();} public String username(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();} public boolean valid(String t){try{username(t);return true;}catch(Exception e){return false;}}}